entries[43597] = { ["name"] = "Vorlage: Titanring der Frostwache", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Juwelenschleifen (420)\nBenutzen: Lehrt Euch die Herstellung eines Titanrings der Frostwache.\n\nTitanring der Frostwache\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nFinger\n+100 Ausdauer\n+68 Frostwiderstand\n\nRoter Sockel\nSockelbonus: +6 Ausdauer\n\nBenötigt Stufe 80\nVerkaufspreis:\nBenötigt Titanbarren (2), Äonenwasser (3), Äonenfeuer (3), Gefrorene Kugel" }
entries[43599] = { ["name"] = "Großer Blizzardbär", ["text"] = "Accountgebunden\nReittier\nBenötigt Stufe 20\nBenötigt Unerfahrener Reiter\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen großen Blizzardbären oder gibt ihn wieder frei. Die Geschwindigkeit dieses Reittieres ist von Eurer Reitfertigkeit abhängig." }
entries[43600] = { ["name"] = "Harpune aus Brunnhildar", ["text"] = "Zweihändig Stangenwaffe\n176 - 265 Schaden Tempo 3.80\n(58.03 Schaden pro Sekunde)\nHaltbarkeit 85 / 85\nBenötigt Stufe 75\nAnlegen: Verursacht pro Schwung 4 to 6 zusätzlichen Frostschaden.\nVerkaufspreis:" }
entries[43601] = { ["name"] = "Großaxt aus Brunnhildar", ["text"] = "Zweihändig Axt\n186 - 279 Schaden Tempo 4.00\n(58.13 Schaden pro Sekunde)\nHaltbarkeit 85 / 85\nBenötigt Stufe 75\nAnlegen: Verursacht pro Schwung 4 to 6 zusätzlichen Frostschaden.\nVerkaufspreis:" }
