entries[43608] = { ["name"] = "Kupferklammers flüchtiges Öl", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Setzt eine gepanzerte Soldatenattrappe an der Zerbrochenen Front zusammen. (20 Sek. Abklingzeit)" }
entries[43609] = { ["name"] = "Knochenhaufen", ["text"] = "Questgegenstand\n\"Ein gefallener Soldat, gänzlich ohne Fleisch.\"" }
entries[43610] = { ["name"] = "Zurückgelassener Helm", ["text"] = "Questgegenstand\n\"Ein schlachterprobter Helm der Allianz.\"" }
entries[43611] = { ["name"] = "Krolspalter", ["text"] = "Wird beim Anlegen gebunden\nEinhändig Schwert\n261 - 485 Schaden Tempo 2.60\n(143.46 Schaden pro Sekunde)\n+36 Beweglichkeit\n+71 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 80\nAnlegen: Erhöht die kritische Trefferwertung um 28.\nVerkaufspreis:" }
entries[43612] = { ["name"] = "Rückgratschlitzer", ["text"] = "Wird beim Anlegen gebunden\nWurfwaffe Wurfwaffe\n328 - 493 Schaden Tempo 2.20\n(186.59 Schaden pro Sekunde)\n+26 Beweglichkeit\n+44 Ausdauer\nBenötigt Stufe 80\nAnlegen: Erhöht die Trefferwertung um 25.\nVerkaufspreis:" }
entries[43613] = { ["name"] = "Die Dämmerklinge", ["text"] = "Wird beim Anlegen gebunden\nEinhändig Dolch\n206 - 310 Schaden Tempo 1.80\n(143.33 Schaden pro Sekunde)\nHaltbarkeit 75 / 75\nBenötigt Stufe 80\nTrefferchance: Ihr erhaltet 10 Sek. lang eine zusätzliche kritische Trefferwertung von 155. Dieser Effekt ist bis zu 3-mal stapelbar.\nVerkaufspreis:" }
entries[43614] = { ["name"] = "Zerbrochene Phiole Zornelixier", ["text"] = "Benutzen: Transmutiert 5 zerbrochene Phiolen Zornelixier zu einem Zornelixier.\nVerkaufspreis:" }
entries[43615] = { ["name"] = "Saurfangs Schlachtrüstung", ["text"] = "Questgegenstand\nEinzigartig" }
entries[43616] = { ["name"] = "Zurückgelassene Rüstung", ["text"] = "Questgegenstand\n\"Eine durchstochene Brustplatte der Allianz.\"" }
entries[43620] = { ["name"] = "Zerbrochene Phiole Zaubermachtelixier", ["text"] = "Benutzen: Transmutiert 5 zerbrochene Phiolen Zaubermachtelixier zu einem Zaubermachtelixier.\nVerkaufspreis:" }
entries[43621] = { ["name"] = "Zerbrochene Phiole Noggenfoggers Elixier", ["text"] = "Benutzen: Transmutiert 5 zerbrochene Phiolen Noggenfoggers Elixier zu einem Noggenfoggers Elixier.\nVerkaufspreis:" }
entries[43622] = { ["name"] = "Froststahlschließkassette", ["text"] = "Verschlossen\nBenötigt Schlossknacken (375)\nVerkaufspreis:" }
entries[43624] = { ["name"] = "Titanschließkassette", ["text"] = "Verschlossen\nBenötigt Schlossknacken (400)\nVerkaufspreis:" }
entries[43626] = { ["name"] = "Leckerli für glückliche Haustiere", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Füttert Euer Haustier mit einem Leckerli.\nVerkaufspreis:" }
entries[43627] = { ["name"] = "Thralls Goldmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n\"Grom, möget Ihr in Frieden ruhen, alter Freund.\"\nVerkaufspreis:" }
entries[43628] = { ["name"] = "Lady Jaina Prachtmeers Goldmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n\"Arthas, mein Liebster, bitte komm zu mir zurück.\"\nVerkaufspreis:" }
entries[43629] = { ["name"] = "Uther Lichtbringers Goldmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n\"Der junge Arthas muss Geduld lernen und seine Macht im Zaum halten. Ich werde dafür beten, dass er eines Tages lernen wird, mit Fürsorge statt mit Gewalt zu gebieten.\"\nVerkaufspreis:" }
entries[43630] = { ["name"] = "Tirion Fordrings Goldmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n\"Ich wünsche mir, dass mein teurer Taelan stark genug werden wird, um diejenigen zu schützen, die ihm am Herzen liegen.\"\nVerkaufspreis:" }
entries[43631] = { ["name"] = "Terons Goldmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n\"Wünsche sind ein Zeitvertreib für Toren. Nehmt diese Münze als Lohn für Euer kostbares Auge.\"\nVerkaufspreis:" }
entries[43632] = { ["name"] = "Sylvanas Windläufers Goldmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n\"Ich hoffe, dass meine Schwestern und ich gemeinsam aufwachsen und gemeinsam heiraten können. Diese Münze scheint sehr alt zu sein.\"\nVerkaufspreis:" }
entries[43633] = { ["name"] = "Prinz Kael'thas Sonnenwanderers Goldmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n\"Dieser junge Lehrling namens Jaina ist ziemlich attraktiv für einen Menschen. Ich hoffe, dass sie erkennt, wie elegant und mächtig ich bin.\"\nVerkaufspreis:" }
entries[43634] = { ["name"] = "Lady Katrana Prestors Goldmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n\"Hör mir zu, kleiner Wunschbrunnen. Wenn du weißt, was gut für dich ist, dann wirst du mir all deine Macht geben.\"\nVerkaufspreis:" }
entries[43635] = { ["name"] = "Kel'Thuzads Goldmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n\"Manchmal... wünschte ich, dass mich irgendjemand mal ganz lang umarmen würde.\"\nVerkaufspreis:" }
entries[43636] = { ["name"] = "Chromies Goldmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n\"Ich wünschte, dass mich jemand nur ein einziges Mal grüßen würde, ohne dabei einen dummen Witz über Gnome oder Zeitreisen machen zu müssen.\"\nVerkaufspreis:" }
entries[43637] = { ["name"] = "Brann Bronzebarts Goldmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n\"Brann Bronzebart war hier.\"\nVerkaufspreis:" }
entries[43638] = { ["name"] = "Arugals Goldmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n\"Eines Tages möchte ich mich in meinem eigenen sauberen, kleinen Anwesen mit ein paar Hunden an meiner Seite niederlassen.\"\nVerkaufspreis:" }
entries[43639] = { ["name"] = "Arthas' Goldmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n\"Ich habe schon ein Königreich in Aussicht; ein Land, über das ich herrschen kann. Was will ich mehr? Ein richtig langer Winterurlaub, das wär' was...\"\nVerkaufspreis:" }
entries[43640] = { ["name"] = "Archimondes Goldmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n\"Ich möchte wissen, wie du meinen Zorn überstehen konntest, kleiner Brunnen.\"\nVerkaufspreis:" }
entries[43641] = { ["name"] = "Anduin Wrynns Goldmünze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft diese Münze zurück in den Brunnen von Dalaran.\n\"Wünschte, ich würde endlich mal erwachsen werden. Hab' das Gefühl, dass ich schon seit 'ner Ewigkeit zehn bin.\"\nVerkaufspreis:" }
entries[43643] = { ["name"] = "Prinz Magni Bronzebarts Silbermünze", ["text"] = "\"Ich hoffe, dass mein Vater und Bruder länger leben werden als ich. Ich würde keinen so guten König abgeben.\"\nVerkaufspreis:" }
entries[43644] = { ["name"] = "Silbermünze eines Bauern", ["text"] = "\"Ich bin so vergesslich! Wünschte, mein Gedächtnis wäre besser. Halt, habe ich nicht schon 'ne Münze hier reingeworfen?\"\nVerkaufspreis:" }
entries[43645] = { ["name"] = "Verbogener Angelhaken", ["text"] = "\"Sieht so aus, als hätte jemand versucht, in dem Brunnen herumzufischen. Wer würde so etwas nur tun?\"\nVerkaufspreis:" }
entries[43646] = { ["name"] = "Brunnengoldfisch", ["text"] = "Benötigt Stufe 65\nBenutzen: Stellt im Verlauf von 30 Sek. insgesamt 7500 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[43647] = { ["name"] = "Schillerndes Fischchen", ["text"] = "Benötigt Stufe 70\nBenutzen: Stellt im Verlauf von 30 Sek. insgesamt 18480 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[43650] = { ["name"] = "Rostiger Gefängnisschlüssel", ["text"] = "Wird beim Aufheben gebunden\n\"Ähnelt einem Schlüssel, mit dem man Unterwasserschatzkisten öffnen kann...\"\nVerkaufspreis:" }
entries[43651] = { ["name"] = "Pfiffis Angelrute", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Angelrute\n447 - 672 Schaden Tempo 3.00\n(186.50 Schaden pro Sekunde)\nHaltbarkeit 95 / 95\nBenötigt Angeln (1)\nAnlegen: Fertigkeit im Angeln um 1000 erhöht.\n\"Diese Angelrute auch nur zu halten, lässt Euch vor Aufregung zittern - ist vielleicht das Tollste, das Ihr je gesehen habt.\"\nVerkaufspreis:" }
entries[43652] = { ["name"] = "Glitschiger Aal", ["text"] = "Benötigt Stufe 70\nBenutzen: Stellt im Verlauf von 30 Sek. 18480 Gesundheit wieder her. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 40 Ausweichwertung.\nVerkaufspreis:" }
entries[43653] = { ["name"] = "Angefressener Fisch", ["text"] = "\"Auf dem Kadaver sind kleine Bisswunden zu sehen.\"\nVerkaufspreis:" }
entries[43654] = { ["name"] = "Foliant der Dämmerung", ["text"] = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+9 Ausdauer\n+5 Intelligenz\nBenötigt Stufe 20\nVerkaufspreis:" }
entries[43655] = { ["name"] = "Buch des Überlebens", ["text"] = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+7 Ausdauer\nBenötigt Stufe 20\nAnlegen: Stellt alle 5 Sek. 7 Gesundheit wieder her.\nVerkaufspreis:" }
entries[43656] = { ["name"] = "Foliant der Könige", ["text"] = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+6 Ausdauer\nBenötigt Stufe 30\nAnlegen: Erhöht die kritische Trefferwertung um 6.\nAnlegen: Erhöht die Trefferwertung um 5.\nBenutzen: Erhöht Eure Werte 1 Min. lang um 10. (10 Min Abklingzeit)\nVerkaufspreis:" }
entries[43657] = { ["name"] = "Königlicher Almanach der Fluchtwege", ["text"] = "Wird beim Anlegen gebunden\nIn Schildhand geführt\nBenötigt Stufe 30\nAnlegen: Erhöht die Tempowertung um 11.\nBenutzen: Heilt Euch um 270 to 330. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[43658] = { ["name"] = "Teilweise angerostete Feile", ["text"] = "\"Die Feile hat einen leichten Grünstich.\"\nVerkaufspreis:" }
entries[43659] = { ["name"] = "Blutiger messerähnlicher Gegenstand", ["text"] = "Einhändig Dolch\n93 - 174 Schaden Tempo 2.00\n(66.75 Schaden pro Sekunde)\nHaltbarkeit 55 / 55\nBenötigt Stufe 70\n\"Das spitze Ende des Gegenstandes sieht aus, als wäre es reichlich genutzt worden.\"\nVerkaufspreis:" }
entries[43660] = { ["name"] = "Leitfaden für Feuerschlucker", ["text"] = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+10 Intelligenz\nBenötigt Stufe 40\nAnlegen: Erhöht die kritische Trefferwertung um 9.\nBenutzen: Atmet Feuer auf Feinde vor Euch und verursacht 278 to 322 Feuerschaden. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[43661] = { ["name"] = "Buch der Sterne", ["text"] = "Wird beim Anlegen gebunden\nIn Schildhand geführt\nBenötigt Stufe 40\nAnlegen: Erhöht die Trefferwertung um 14.\nBenutzen: Stellt 315 to 385 Mana wieder her. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[43662] = { ["name"] = "Axt des Brandschatzers", ["text"] = "Questgegenstand\nEinzigartig\n\"Ihr würdet von dieser Axt erwarten, dass sie außergewöhnlich scharf ist, doch das ist sie nicht. Der Vrykul muss sich wohl eher auf seine enorme Kraft verlassen haben, um seine Gegner in Stücke zu hauen.\"" }
entries[43663] = { ["name"] = "Sturmgebundener Foliant", ["text"] = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+15 Ausdauer\n+10 Intelligenz\nBenötigt Stufe 50\nAnlegen: Erhöht die kritische Trefferwertung um 9.\nBenutzen: Schockt einen Gegner und verursacht 12 to 800 Naturschaden. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[43664] = { ["name"] = "Handbuch der Wolken", ["text"] = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+14 Ausdauer\n+10 Intelligenz\n+9 Willenskraft\nBenötigt Stufe 50\nBenutzen: Erhöht Eure Willenskraft 1 Min. lang um 50. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[43665] = { ["name"] = "Keristraszas gebrochenes Herz", ["text"] = "Questgegenstand\nEinzigartig\n\"Das tragische Ende einer traurigen Geschichte. Wäre Keristrasza doch nur nicht von Malygos malträtiert und in den Wahnsinn getrieben worden.\"" }
entries[43666] = { ["name"] = "Höllenfeuerfoliant", ["text"] = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+28 Intelligenz\n+20 Feuerwiderstand\nBenötigt Stufe 60\nVerkaufspreis:" }
entries[43667] = { ["name"] = "Buch der cleveren Tricks", ["text"] = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+36 Ausdauer\nBenötigt Stufe 60\nAnlegen: Erhöht die kritische Trefferwertung um 9.\nAnlegen: Erhöht die Trefferwertung um 15.\nBenutzen: Erhöht Eure Ausweichwertung 15 Sek. lang um 200. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[43668] = { ["name"] = "Leylinienempfänger", ["text"] = "Questgegenstand\nEinzigartig\n\"Ihr seid Euch nicht so ganz sicher, was Ihr davon halten sollt. Er steckt auf jeden Fall voller arkaner Magie. Doch wie kann etwas so Kleines nur so wichtig sein?\"" }
entries[43669] = { ["name"] = "Medaillon der verstorbenen Königin", ["text"] = "Questgegenstand\nEinzigartig\n\"Die einzige Erinnerung, die König Ymiron an seine Geliebte, Königin Angerboda, hatte.\"" }
entries[43670] = { ["name"] = "Verzaubertes Tiki des Propheten", ["text"] = "Questgegenstand\nEinzigartig\n\"Mit dem Ableben seines Trägers scheint es auch all sein Mojo verloren zu haben.\"" }
entries[43671] = { ["name"] = "Glyphe 'Eisige Pfade'", ["text"] = "Klassen: Todesritter\nBenötigt Stufe 61\nBenutzen:\nEure Fähigkeit 'Eisige Pfade' ermöglicht Euch, von größeren Höhen zu fallen ohne Schaden zu erleiden.\nVerkaufspreis:" }
entries[43672] = { ["name"] = "Glyphe 'Unnachgiebiger Griff'", ["text"] = "Klassen: Todesritter\nBenötigt Stufe 55\nBenutzen:\nWenn Eure Fähigkeit 'Todesgriff' fehlschlägt, weil das Ziel dagegen immun ist, wird ihre Abklingzeit zurückgesetzt.\nVerkaufspreis:" }
entries[43673] = { ["name"] = "Glyphe 'Schwarzes Tor'", ["text"] = "Klassen: Todesritter\nBenötigt Stufe 55\nBenutzen:\nVerringert die Zauberzeit Eures Zaubers 'Schwarzes Tor' um 60%.\nVerkaufspreis:" }
entries[43674] = { ["name"] = "Glyphe 'Spurt'", ["text"] = "Klassen: Druide\nBenötigt Stufe 26\nBenutzen:\nVerkaufspreis:" }
entries[43675] = { ["name"] = "Fandral Hirschhaupts Silbermünze", ["text"] = "\"Der Krieg der Sandstürme... Wünschte, ich könnte vergessen, dass er jemals stattgefunden hat.\"\nVerkaufspreis:" }
entries[43676] = { ["name"] = "Arkanist Doans Silbermünze", ["text"] = "\"Oh, wieso wollt Ihr mir einfach keine Beachtung schenken? Ich würde Euch überall hin folgen, Abbendis. Ich wünschte, Ihr würdet mich zur Kenntnis nehmen...\"\nVerkaufspreis:" }
entries[43677] = { ["name"] = "Hochtüftler Mekkadrills Silbermünze", ["text"] = "\"Wie kann dieser Brunnen nur funktionieren? Ich frage mich, ob ich selbst einen bauen könnte.\"\nVerkaufspreis:" }
entries[43678] = { ["name"] = "Antonidas Silbermünze", ["text"] = "\"Gib mir die Stärke, Dinge hinzunehmen, die ich nicht ändern kann, den Mut, Dinge zu ändern, die ich ändern kann, und die Weisheit, das eine vom anderen zu unterscheiden.\"\nVerkaufspreis:" }
entries[43679] = { ["name"] = "Muradin Bronzebarts Silbermünze", ["text"] = "\"Möge uns das Heilige Licht auf unserer Expedition in den eisigen Norden beschützen.\"\nVerkaufspreis:" }
entries[43680] = { ["name"] = "König Varian Wrynns Silbermünze", ["text"] = "\"Ich wünschte, der Aufstand zuhause würde sich bald wieder legen. Würde nicht wollen, dass irgendjemand verletzt wird.\"\nVerkaufspreis:" }
entries[43681] = { ["name"] = "König Terenas Menethils Silbermünze", ["text"] = "\"Möge mein Sohn Arthas immer im besten Interesse seines Volkes handeln.\"\nVerkaufspreis:" }
entries[43682] = { ["name"] = "König Anasterian Sonnenwanderers Silbermünze", ["text"] = "\"Ich hoffe, der junge Kael'thas ist sich bewusst, dass er eines Tages unser Volk führen muss.\"\nVerkaufspreis:" }
entries[43683] = { ["name"] = "Khadgars Silbermünze", ["text"] = "\"Turalyon und Alleria, wo auch immer Ihr seid, möge es Euch wohl ergehen.\"\nVerkaufspreis:" }
entries[43684] = { ["name"] = "Medivhs Silbermünze", ["text"] = "\" \"\nVerkaufspreis:" }
entries[43685] = { ["name"] = "Maiev Schattensangs Silbermünze", ["text"] = "\"Wo ist Illidan?\"\nVerkaufspreis:" }
entries[43686] = { ["name"] = "Allerias Silbermünze", ["text"] = "\"Mögen meine Schwestern ihr volles Potential erkennen; mögen ihre Taten den Namen Windläufer bekannt machen.\"\nVerkaufspreis:" }
entries[43687] = { ["name"] = "Aegwynns Silbermünze", ["text"] = "\"Ich wünschte wirklich, dass Ihr Magier endlich damit aufhören würdet, die Köpfe in Eure eigenen... Bücher zu stecken.\"\nVerkaufspreis:" }
entries[43688] = { ["name"] = "Dokument des Tränenbruchs", ["text"] = "Questgegenstand" }
entries[43689] = { ["name"] = "Geschäftsbuch des Tränenbruchs", ["text"] = "Questgegenstand" }
entries[43690] = { ["name"] = "Zeitplan des Tränenbruchs", ["text"] = "Questgegenstand" }
entries[43691] = { ["name"] = "Karte des Tränenbruchs", ["text"] = "Questgegenstand" }
entries[43693] = { ["name"] = "Überrest von Akalis Mojo", ["text"] = "Questgegenstand\nEinzigartig\n\"Schwer zu glauben, dass dies alles ist, was von dem einst so mächtigen Rhinozerosgott übrig geblieben ist.\"" }
entries[43694] = { ["name"] = "Ertrunkene Ratte", ["text"] = "\"Sieht so aus, als wäre das Schwimmen im Suppentopf diesmal nicht so gut gelaufen.\"\nVerkaufspreis:" }
entries[43695] = { ["name"] = "Halbvolle Flasche Gefängnisfusel", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\n\"Auch als Farblösemittel geeignet.\"\nVerkaufspreis:" }
entries[43696] = { ["name"] = "Halbleere Flasche Gefängnisfusel", ["text"] = "Benutzen: Ein starkes alkoholisches Getränk.\n\"Auch als Farblösemittel geeignet.\"\nVerkaufspreis:" }
entries[43697] = { ["name"] = "Artefakt aus der Heimatwelt der Nathrezim", ["text"] = "Questgegenstand\nEinzigartig\n\"Was für eine seltsame Konstruktion. Es muss einer befremdlichsten Gegenstände sein, den Ihr je zu Gesicht bekommen habt.\"" }
entries[43698] = { ["name"] = "Riesige Kanalratte", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Eure riesige Kanalratte beschwören oder wieder freigeben.\nVerkaufspreis:" }
entries[43699] = { ["name"] = "Datenscheibe: Fluch des Fleisches", ["text"] = "Questgegenstand\nEinzigartig\n\"Auf diesem Ding befinden sich Informationen? Wie? Da steht gar nichts geschrieben!\"" }
entries[43701] = { ["name"] = "Kupfermünze eines Fußsoldaten", ["text"] = "\"Wünschte, ich hätte die gleiche Aufgabe wie einer meiner Cousins: Nichts weiter tun, als unbekümmert Holz herumschleppen...\"\nVerkaufspreis:" }
entries[43702] = { ["name"] = "Alonsus Faols Kupfermünze", ["text"] = "\"Hoffe, dass ich eines Tages den Weg des Lichts unter dem einfachen Volke verbreiten und ihnen den Wert der Drei Tugenden näher bringen kann.\"\nVerkaufspreis:" }
entries[43703] = { ["name"] = "Ansirems Kupfermünze", ["text"] = "\"Für meine Tochter wünsche ich mir Glück und Anerkennung. Sie fühlt sich hier so fehl am Platz...\"\nVerkaufspreis:" }
entries[43704] = { ["name"] = "Attumens Kupfermünze", ["text"] = "\"Kann ich einen bequemeren Sattel haben? Mein Hintern tut weh.\"\nVerkaufspreis:" }
entries[43705] = { ["name"] = "Danaths Kupfermünze", ["text"] = "\"Hoffe, ein Troll stirbt genau... JETZT.\"\nVerkaufspreis:" }
entries[43706] = { ["name"] = "Dornaas glänzende Kupfermünze", ["text"] = "\"Wünschte, dieser Trottel Arthas würde in einen Haufen Magnataurenmist fallen!\"\nVerkaufspreis:" }
entries[43707] = { ["name"] = "Etriggs Kupfermünze", ["text"] = "\"Möge Tirion auf seiner Suche hier in Nordend Erfolg haben oder einen ehrenhaften Tod im Kampf finden.\"\nVerkaufspreis:" }
entries[43708] = { ["name"] = "Elling Trias' Kupfermünze", ["text"] = "\"Ein Schurke zu sein ist harte Arbeit. Hoffe, dass ich eines Tages meiner einzigen wahren Leidenschaft nachgehen kann...\"\nVerkaufspreis:" }
entries[43709] = { ["name"] = "Falstad Wildhammers Kupfermünze", ["text"] = "\"Hoffe, dass sich die Dinge irgendwann einmal ändern werden.\"\nVerkaufspreis:" }
entries[43710] = { ["name"] = "Genns Kupfermünze", ["text"] = "\"Pfff, die Brunnen in Gilneas könnten zehn Mal so viele Wünsche erfüllen wie die in Dalaran!\"\nVerkaufspreis:" }
entries[43711] = { ["name"] = "Inigos Kupfermünze", ["text"] = "\"Ich wünschte, mein Vater wär' wieder da...\"\nVerkaufspreis:" }
entries[43712] = { ["name"] = "Krasus' Kupfermünze", ["text"] = "\"Meine Gebete gehen an meine Brüder und Schwestern, die noch immer im Herzen von Grim Batol Qualen erleiden müssen. Ich WERDE sie befreien.\"\nVerkaufspreis:" }
entries[43713] = { ["name"] = "Krylls Kupfermünze", ["text"] = "\"Bumm. Bumm? Ich wünsche mir einen Bumm. Na los, mach bumm! Die Münze muss kaputt sein. Frage mich, ob sie explodieren wird.\"\nVerkaufspreis:" }
entries[43714] = { ["name"] = "Landro Fernblicks Kupfermünze", ["text"] = "\"Ich wünschte, ich hätte die Münze behalten...\"\nVerkaufspreis:" }
entries[43715] = { ["name"] = "Moloks Kupfermünze", ["text"] = "\"Nur einmal - mehr will ich gar nicht - nur einmal möchte ich mit dem Mädchen reiten...\"\nVerkaufspreis:" }
entries[43716] = { ["name"] = "Murkys Kupfermünze", ["text"] = "\"Ich wünschte, das Wasser in Nordend wäre nicht so kalt - es macht mich müde.\"\nVerkaufspreis:" }
entries[43717] = { ["name"] = "Prinzessin Calia Menethils Kupfermünze", ["text"] = "\"Ich hoffe, dass dieser gutaussehende Edelmann Lord Prestor mich bemerkt! Was für ein Traummann!\"\nVerkaufspreis:" }
entries[43718] = { ["name"] = "Soldat Marcus Jonathans Kupfermünze", ["text"] = "\"Ich wünsche mir, dass ich mir eines Tages einen prächtigen, buschigen Schnauzbart wachsen lassen werde.\"\nVerkaufspreis:" }
entries[43719] = { ["name"] = "Salandrias Kupfermünze", ["text"] = "\"Eines Tages werde ich mächtiger sein, als all diese Magier!\"\nVerkaufspreis:" }
entries[43720] = { ["name"] = "Knappe Rowes Kupfermünze", ["text"] = "\"Ich hoffe, dass ich irgendwann aus Sturmwind verlegt werde und Cersei wiedersehen kann. In dieser Stadt passiert nie etwas Gutes.\"\nVerkaufspreis:" }
entries[43721] = { ["name"] = "Stalvans Kupfermünze", ["text"] = "\"Ihr Magier weigert euch, mir das zu geben, was das unweigerliche Schicksal zweier sich Liebender beschleunigt, nur weil einer von beiden zu naiv ist, um es zu erkennen? Ich wünsche euch allen den Untergang.\"\nVerkaufspreis:" }
entries[43722] = { ["name"] = "Vereesas Kupfermünze", ["text"] = "\"Asto're da shan're. Turus Fulo Il'amare, A'Talah Adore. Isera'duna...\"\nVerkaufspreis:" }
entries[43723] = { ["name"] = "Vargoths Kupfermünze", ["text"] = "\"Ich wünschte, Käpt'n Sanders würde sich mit meiner Weinlieferung etwas beeilen.\"\nVerkaufspreis:" }
entries[43724] = { ["name"] = "Himmlischer Rubinring", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Ring? Es sieht eher wie eine Halskette aus, noch dazu eine schwere!\"" }
entries[43725] = { ["name"] = "Glyphe 'Geisterwolf'", ["text"] = "Klassen: Schamane\nBenötigt Stufe 25\nBenutzen:\nIn Geisterwolfgestalt wird Euer Bewegungstempo um zusätzlich 5% erhöht.\nVerkaufspreis:" }
entries[43726] = { ["name"] = "Die unnütze Krone Anub'araks", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Gruftlord trug sie noch immer, obwohl er schon vor langer Zeit, als er in den Dienst des Lichkönigs trat, seinen Königstitel verloren hatte.\"" }
